css_extra:
.portada { padding: 96px 0 72px; background: linear-gradient(180deg, #FFF8EC 0%, #FFFFFF 100%); }
.portada h1 { font-size: clamp(2.2rem, 5vw, 3.4rem); margin-top: 0; }
.entradilla { font-size: 1.25rem; max-width: 760px; color: #3C4043; }
.bloque.gris { background: #F8F9FA; }
.caja { background: #fff; border: 1px solid #E8EAED; border-radius: 16px; padding: 24px; height: 100%; }
.caja h3 { font-size: 1.15rem; margin-top: 0; color: #202124; }
.lente { border-top: 4px solid #F29900; }
.aviso-sobrio { font-size: .95em; color: #5F6368; border-left: 3px solid #F29900; padding-left: 14px; }
.pie .columnas { gap: 24px; }
